"""Which Workpeg function base image a new function project builds FROM.

Every function template starts ``FROM`` the base this SDK's release pipeline
pushes, at one exact version::

    FROM registry.gitlab.com/workpeg/workpeg-sdk/pegfn-base:<X.Y.Z>

The base carries the SDK, the non-root ``appuser`` and the runtime's
ENTRYPOINT, so a bundle adds only its own code and the wheels it vendors.
Workpeg builds a function with no network, so the base is the only way the
SDK gets into the image at all; the api refuses any other tag than an exact
``X.Y.Z`` (``_allowed_base`` in the api's ``function_container.py``).

The version written is the SDK the developer has installed, read when
``workpeg function new`` or ``workpeg project create`` runs, so the image a
project builds on is the runtime it was tested against locally. A dev tree
installs as version ``0``, which names no image, so it writes the newest
release its own ``CHANGELOG.md`` records instead, and refuses when it cannot
find one rather than write a ``FROM`` that cannot be pulled.
"""
from __future__ import annotations

import re
from pathlib import Path

#: The image the release pipeline pushes (``pegfn_base`` in .gitlab-ci.yml),
#: and the one name the api accepts besides the official ``python`` images.
IMAGE = "registry.gitlab.com/workpeg/workpeg-sdk/pegfn-base"

#: Substituted into the function templates' Dockerfiles.
PLACEHOLDER = "REPLACE_PEGFN_BASE_VERSION"

#: A release version as the api reads one: three dot-separated numbers.
# The api's own rule for the base's tag (installed_pegs/function_container.py
# _RELEASE): at most four digits in each part, no leading zero. A version
# this accepts and the api refuses would name a FROM no install can build.
RELEASE = re.compile(
    r"(0|[1-9][0-9]{0,3})\.(0|[1-9][0-9]{0,3})\.(0|[1-9][0-9]{0,3})")

_HEADING = re.compile(r"^## \[((?:0|[1-9][0-9]*)(?:\.(?:0|[1-9][0-9]*)){2})\]",
                      re.MULTILINE)


class BaseVersionError(Exception):
    """No released base image can be named for this SDK."""


def _installed_version() -> str:
    from workpeg import __version__
    return __version__


def _source_changelog() -> Path:
    # src/workpeg/function_base.py -> the repository root, in a dev tree.
    return Path(__file__).resolve().parents[2] / "CHANGELOG.md"


def base_version(version: str | None = None,
                 changelog: Path | None = None) -> str:
    """The exact ``X.Y.Z`` of the base image a new project should use."""
    version = _installed_version() if version is None else version
    if RELEASE.fullmatch(version):
        return version
    path = _source_changelog() if changelog is None else changelog
    try:
        found = _HEADING.search(path.read_text(encoding="utf-8"))
    except OSError:
        found = None
    if found:
        return found.group(1)
    raise BaseVersionError(
        f"This workpeg is version '{version}', not a release, and no "
        f"released version was found in {path}, so there is no "
        f"{IMAGE} tag to build on. Install a released SDK "
        f"(pip install workpeg) and run the command again.")


def base_image(version: str | None = None,
               changelog: Path | None = None) -> str:
    """``IMAGE:<X.Y.Z>`` for the base a new project should use."""
    return f"{IMAGE}:{base_version(version, changelog)}"


def fill(text: str, version: str | None = None) -> str:
    """*text* with the template's base-version placeholder filled in."""
    if PLACEHOLDER not in text:
        return text
    return text.replace(PLACEHOLDER, base_version(version))
